"""Unit 2568 of layers.15.mlp.down_proj: a Russian-text unit.

In plain terms: the unit is quiet in English and most other text. Inside Russian it takes a
sign that depends on the kind of token, and it is stronger the more Russian the last 16 tokens are:

  * a Russian preposition that starts a word (в, на, с, по, у, из, от, за, под, ...) pushes it
    positive;
  * a Russian word fragment with no leading space (word endings and pieces, most strongly the
    adjective endings -ной, -ных, -ные, -ого, ...) pushes it negative;
  * other Russian words that start with a space are slightly negative;
  * punctuation (commas, dashes, colons) inside Russian text pushes it negative;
  * any other token inside Russian text is mildly negative.

Everywhere else (English, code, digits) the prediction is 0.
"""

import regex

READS = ()

CYRILLIC = regex.compile(r"\p{Script=Cyrillic}")
PREPOSITIONS = {
    " в", " на", " с", " по", " у", " из", " от", " к", " за", " под",
    " об", " при", " для", " о", " со", " во",
}
ADJECTIVE_ENDINGS = {"ной", "ных", "ные", "ного", "ная", "ый", "ых", "ой", "ую", "ими", "ыми", "ому"}


def is_punctuation(text):
    return text.strip() != "" and not any(ch.isalnum() for ch in text)


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    # How Russian the text is: share of Cyrillic tokens among the last 16 in this document.
    recent = [t for t, d in zip(prefix.token_strings[-16:], prefix.document_ids[-16:]) if d == doc]
    russian = sum(bool(CYRILLIC.search(t)) for t in recent) / len(recent)
    if CYRILLIC.search(token):
        if not token.startswith(" "):
            # A word fragment; adjective endings are the most negative.
            value = -1.9 + 0.3 * russian
            if token in ADJECTIVE_ENDINGS:
                value -= 1.6 + 1.8 * russian
        elif token in PREPOSITIONS:
            value = 0.8 + 1.7 * russian
        else:
            value = -0.9
    elif is_punctuation(token):
        value = -3.9 * russian
    else:
        value = -1.4 * russian
    return carry, value

"""Demonstrative determiners and noun-phrase modifiers, layer 15 MLP down_proj, component 2570.

What it does: the component is a weak, context-dependent detector for words that open a
noun phrase whose head noun is still to come. It is strongest on demonstrative determiners
("this", "cette", "dieser", "这个", "этот") and weaker on "these"/"such", on superlative and
ordinal modifiers ("the biggest", "the first", "the latest"), and on "that" when it is a
determiner after a preposition ("in that case") rather than a complementizer ("said that").
Everything else it predicts as 0, which is also its typical value (the activation is
roughly zero-mean with a wide spread, so most of it is not captured by word identity).

Why these words: the largest activations in the data are on demonstratives and
superlative/evaluative adjectives directly before a noun ("[this] product", "the most
[popular] ...", "the [last] page"). Word identity alone explains only about 5% of the
variance (about 14% with a full per-word table), so this is a partial description.
"""

READS: tuple[str, ...] = ()

# Demonstrative determiners and their translations: the strongest trigger.
DEMONSTRATIVE = {
    "this": 2.1, "cette": 3.0, "ce": 1.8, "dieser": 2.4, "diese": 1.9, "dieses": 1.9,
    "este": 1.8, "esta": 2.0, "этот": 3.4, "этом": 2.3, "этого": 2.2,
    "该": 3.0, "这": 1.3, "这个": 2.2, "这种": 1.2, "此": 1.4, "這": 1.7, "この": 1.3,
}  # fmt: skip

# Weaker determiners.
WEAK = {"these": 0.8, "such": 0.7}

# Ordinals and superlatives, which modify a following noun.
MODIFIER = {
    "first": 0.9, "last": 0.9, "latest": 0.9, "new": 0.6, "final": 0.9,
    "biggest": 1.8, "largest": 1.8, "greatest": 1.5, "best": 1.5, "highest": 1.0,
    "lowest": 1.0, "favorite": 1.8, "most": 1.0, "popular": 1.5, "famous": 1.5,
    "dangerous": 1.2, "important": 0.9,
}  # fmt: skip

# Prepositions before which "that" is a demonstrative determiner ("in that case").
PREPOSITIONS = {"in", "on", "of", "for", "to", "at", "from", "with", "about", "by", "into", "during"}


def word(text):
    return text.strip().lower()


def step(carry, prefix, upstream):
    w = word(prefix.token_strings[-1])
    if w in DEMONSTRATIVE:
        value = DEMONSTRATIVE[w]
    elif w in WEAK:
        value = WEAK[w]
    elif w in MODIFIER:
        value = MODIFIER[w]
    elif w == "that":
        before = word(prefix.token_strings[-2]) if len(prefix.token_strings) > 1 else ""
        value = 2.5 if before in PREPOSITIONS else 0.3
    else:
        value = 0.0
    return carry, float(value)

"""Layer 15, MLP hidden unit 2589 (the component's input direction is this one unit).

The unit is strongly positive at the end of a line of source code that closes a statement
(`...;`, `...();`, `...];`, `...";`), mildly positive where a code line ends in `)`, `]`,
a quote or a comma, and negative on assignment operators (` =`, ` :=`) and on declaration
words (`import`, `const`, `let`, `var`, `static`, ...). Its size is set by how code-like the
recent text is: prose and reasoning text sit near zero, dense code gets the full value.

The program predicts those values. It keeps one running number, the share of recent tokens
that carry code punctuation, and resets it at each document boundary.
"""

READS = ()

CODE_MARKS = set(";{}()[]=<>")
DECLARATION_WORDS = {"import", "const", "let", "var", "static", "final", "private", "public"}


def line_end_value(token):
    """Value of a token that ends a line: set by the last character before the newline."""
    last = token.split("\n")[0].rstrip("\r").rstrip()[-1:]
    if last == ";":
        return 6.3
    if last in (")", "]", '"', "'"):
        return 2.5
    if last == ",":
        return 2.0
    return 0.0


def token_value(token):
    """Value of a token that does not end a line."""
    if token.strip() == "=":
        return -2.2
    if token.strip() == ":=":
        return -5.7
    if token.strip() in DECLARATION_WORDS:
        return -2.4
    if token.endswith(";"):
        return 2.0
    return 0.0


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    new_document = len(prefix.document_ids) < 2 or prefix.document_ids[-2] != prefix.document_ids[-1]
    code = 0.0 if carry is None or new_document else carry
    # running share of recent tokens that carry code punctuation: how code-like the text is
    code = 0.95 * code + (0.05 if any(c in CODE_MARKS for c in token) else 0.0)
    if "\n" in token or "\r" in token:
        value = line_end_value(token)
    else:
        value = token_value(token)
    return code, value * (0.5 + code)

"""Chat-template role tokens, plus a weak offset for digits, spaces and punctuation.

Main signal: the component is strongly negative on the role name "assistant"
right after "<|im_start|>" (the first token of an assistant turn, mean about
-2.6). The role name "user" in that slot gives a weaker negative value (about
-0.4).

Elsewhere the component is a small, diffuse signal. Its average is slightly
below zero on digits, on runs of spaces and on punctuation, so those get
small negative offsets. Everything else is predicted as 0.
"""
import unicodedata

READS = ()

ROLE_VALUES = {"assistant": -2.6, "user": -0.4}
CLASS_VALUES = {"digit": -0.06, "space": -0.05, "punct": -0.035}


def token_class(text):
    if text.strip().isdigit():
        return "digit"
    if text.strip() == "" and text != "":
        return "space"
    if text and all(unicodedata.category(c).startswith("P") or unicodedata.category(c).startswith("S") for c in text):
        return "punct"
    return None


def step(carry, prefix, upstream):
    ids = prefix.token_strings
    same_doc = len(prefix.document_ids) < 2 or prefix.document_ids[-2] == prefix.document_ids[-1]
    if len(ids) >= 2 and same_doc and ids[-2] == "<|im_start|>" and ids[-1] in ROLE_VALUES:
        return carry, ROLE_VALUES[ids[-1]]
    cls = token_class(ids[-1])
    return carry, CLASS_VALUES.get(cls, 0.0)

"""Token-class predictor for layers.15.mlp.down_proj component 2607.

This component's activation is a dense, context-noisy readout (its variance is spread
over many MLP hidden units; no single neuron or short context explains it). What is
predictable is its sign and size by the surface form of the current token:

- strongly negative on file-name extensions of code and data files (".go", ".py",
  ".js", ".rs", ".ts", ".json", ...), which is where its largest negative values sit;
- mildly negative on digits, single letters and letters glued onto a preceding piece
  of a word (sub-word continuations, variable names), i.e. identifier- and
  number-like pieces;
- about zero on spaced English words, and slightly positive on punctuation and
  whitespace.

The program looks only at the newest token, so it needs no carried state.
"""

import re
from collections.abc import Mapping

READS: tuple[str, ...] = ()

CODE_EXTENSIONS = frozenset(
    ".go .py .js .ts .rs .java .php .md .json .h .cpp .yml .yaml .txt .mod .jar "
    ".html .xml .sh .cfg .rb .c .cs .css .csv .lock .zip .pdf .png .jpg .gz "
    ".com .org .net".split()
)


def activation_guess(tok: str) -> float:
    """The predicted activation for one token, by its surface form."""
    if re.fullmatch(r"[0-9]", tok):
        return -0.35  # a digit
    if tok in CODE_EXTENSIONS:
        return -4.5  # a code/data file extension, e.g. ".go"
    if re.fullmatch(r"\.[A-Za-z0-9]{1,6}", tok):
        return -0.7  # any other dotted suffix
    if re.fullmatch(r"[A-Za-z]", tok):
        return -0.35  # a single letter (variable-like)
    if re.fullmatch(r"[A-Za-z]{2,}", tok):
        return -0.2  # a word piece glued onto the previous text
    if re.fullmatch(r" ?[A-Za-z]{2,}", tok):
        return 0.0  # a spaced English word
    if re.fullmatch(r"\s*[^\w\s]+\s*", tok):
        return 0.07  # punctuation
    if tok.isspace():
        return 0.1  # whitespace and newlines
    return -0.05


def step(carry, prefix, upstream: Mapping):
    """The activation at this position: a token-class value for the newest token."""
    return carry, float(activation_guess(prefix.token_strings[-1]))

"""Layer 15 MLP hidden unit 2617, read through this component, as a punctuation rule.

This component's output is almost entirely MLP hidden unit 2617 of layer 15 (about
46% of its input vector's energy sits on that one unit), so its activation tracks that
unit. It is large and positive on the separator tokens that introduce a value, a label,
a type or a definition (':' after a key, ' =' after a variable name, '":' after a JSON
key), smaller on commas, slashes and quotes, and near zero on ordinary words. Its
size and sign also depend on context that a token rule cannot see, so this program
predicts the mean activation of each token class and nothing more. It explains about
8% of the variance: a rough picture, not a full account.

Classes, with the mean activation each gets on a sample of training text:
  - a colon ending a key or label (':', '":', ' :'), not after a digit:  about 2.7
  - a colon after a digit (times like 21:35):                            about 1.3
  - '=' or ' =' right after an identifier (an assignment):               about 2.0
  - '=' elsewhere:                                                       about 0.4
  - a quote followed by a comma or a backtick:                           about 1.3
  - a slash:                                                             about 0.8
  - a comma:                                                             about 0.4
  - any other punctuation-only token:                                    about 0.24
  - whitespace-only token:                                               about 0.12
  - a digit string:                                                      about 0.04
  - a plain word:                                                        about 0.02
  - anything else:                                                       about 0.05
"""

import re
from collections.abc import Mapping

READS: tuple[str, ...] = ()

COLONS = {":", " :", '":', ":\n", "`:", " :="}
EQUALS = {" =", "="}
QUOTE_SEPARATORS = {'",', "',", "`,", "`"}
SLASHES = {"/", "/\n"}
IDENTIFIER = re.compile(r"\s*[A-Za-z_]\w*")
WORD = re.compile(r"\s?[A-Za-z]+")
DIGITS = re.compile(r"\s?\d+")


def is_punctuation(token: str) -> bool:
    body = token.strip()
    return bool(body) and all(not ch.isalnum() for ch in body)


def step(carry, prefix, upstream: Mapping):
    token = prefix.token_strings[-1]
    same_doc = len(prefix.token_strings) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    before = prefix.token_strings[-2] if same_doc else ""
    if token in COLONS:
        return carry, (1.3 if before[-1:].isdigit() else 2.7)
    if token in EQUALS:
        return carry, (2.0 if IDENTIFIER.fullmatch(before) else 0.4)
    if token in QUOTE_SEPARATORS:
        return carry, 1.3
    if token in SLASHES:
        return carry, 0.8
    if token == ",":
        return carry, 0.4
    if is_punctuation(token):
        return carry, 0.24
    if not token.strip():
        return carry, 0.12
    if DIGITS.fullmatch(token):
        return carry, 0.04
    if WORD.fullmatch(token):
        return carry, 0.02
    return carry, 0.05

"""Contrast vs. 'merely' words in Qwen3-1.7B layer 15 MLP (component 2622).

Positive on words that introduce a counter-claim ("but", "however", "though",
"pero", "但", "しかし"). Negative on words that shrink a claim to its bare
essence, "merely"-style "just" / "simply" / "merely" after a copula or pronoun
("it's just a", "they are simply"). Counter-claim words are weaker after a
negated clause, and the shrinking words are stronger there. The token right
after a counter-claim word leans slightly positive, and the one after a
shrinking word leans negative. Everything else is 0.
"""

READS = ()

CONTRAST = {
    "but", "however", "although", "though", "yet", "nevertheless", "whereas",
    "pero", "mais", "aber", "mas", "ma", "ale", "maar", "doch", "но", "nhưng",
    "但", "但是", "しかし",
}
MERELY = {"just", "simply", "merely", "mere", "只是", "просто"}
COPULA = {"is", "are", "was", "were", "'s", "’s", "'re", "'m", "it", "they", "i", "he", "she", "we", "you", ","}
NEGATIONS = {"not", "no", "never", "neither", "nor", "none", "nothing", "without", "cannot"}
SENTENCE_END = {".", "!", "?", "\n"}


def step(carry, prefix, upstream):
    # carry: (negated earlier in this sentence, previous word)
    negated, previous = carry if carry else (False, "")
    if len(prefix.document_ids) > 1 and prefix.document_ids[-1] != prefix.document_ids[-2]:
        negated, previous = False, ""
    word = prefix.token_strings[-1].strip().lower()
    if word in CONTRAST:
        value = 2.0 * (0.6 if negated else 1.0)
    elif word in MERELY:
        value = -4.0 if previous in COPULA else -1.5
        value *= 1.3 if negated else 1.0
    elif previous in CONTRAST:
        value = 0.5
    elif previous in MERELY:
        value = -1.0
    else:
        value = 0.0
    if word in SENTENCE_END:
        negated = False
    elif word in NEGATIONS or word.endswith("n't") or word == "'t":
        negated = True
    return (negated, word), float(value)
